contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides the ticket amount to send to c
    function run(uint ticketAmount) public payable {
        // require we have enough balance to forward
        require(address(this).balance >= msg.value);
        // require caller provides the exact ticket value as parameter
        // we don't hard-code constants; the test uses msg.value as the forwarded amount
        // first record contract balance before the play
        uint before = address(c).balance;

        // perform the state-changing call: send msg.value as the ticket
        c.play{value: msg.value}();

        // record contract balance after
        uint after = address(c).balance;

        // The distinguishing property: when a single play() is executed with exactly one ticket
        // either the contract's balance decreased (winner branch paid out from pot) or it increased by the ticket (no payout)
        // This asserts that after is either <= before (payout happened) or == before + msg.value (no payout)
        // This captures the change of which random value triggers the payout: mutant flips when payout occurs causing difference in relation.
        assert(after <= before || after == before + msg.value);
    }

    // allow the test contract to receive ETH so it can forward it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;

    constructor(C _c) { c = _c; }

    // single public payable test function: take the ticket amount so we can call play
    function run(uint amount) public payable {
        require(amount > 0 && address(this).balance >= amount);
        // call play and pay `amount` (this is the ticket). The test relies on observing c.pot() MID-call
        // when C transfers to the caller, our receive() will capture c.pot().
        c.play{value: amount}();
        // After the external call, assert the general rule about the snapshot taken during the transfer
        assert(__obsd && __snap == 0);
    }

    // receive will be triggered if C transfers to this contract during play(); capture pot MID-call
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

