pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We need to control block.timestamp and block.difficulty so that the fuzzer can pick
    // an msg.sender and a timestamp/difficulty pair that yields random==0.
    // Fuzz parameters: an address actor and a uint256 timestamp (warp). We must ensure
    // the actor is not the zero address and not the contract's address and that timestamp is reasonable.

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 ts) public {
        // Keep actor admissible: nonzero and not the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // The ticket amount is 10; ensure actor has funds
        uint256 amt = 10;
        vm.deal(actor, 1 ether);

        // Bound the timestamp to a realistic block.timestamp range to keep hashing behavior wide
        ts = bound(ts, 1, type(uint64).max);
        vm.warp(ts);

        // Compute the same pseudo-random value as contract would compute for this actor and current block
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        // We are asserting a universal property about the reference: whenever that random == 0,
        // after a play() call with exactly TICKET_AMOUNT from actor, pot becomes 0.
        // This property is violated by the mutant because it triggers payout on random==1 instead.

        // Only proceed with the meaningful case: random must equal 0 for the universal property check.
        vm.assume(random == 0);

        // Make the call as the fuzzed actor, sending exactly TICKET_AMOUNT
        vm.prank(actor);
        c.play{value: amt}();

        // The single assertion: the reference contract should have pot == 0 after this call
        // (read via the public getter). This is true for the reference for all admissible inputs
        // we allowed; the mutant will leave pot != 0 for some such inputs and thus fail this test.
        assertTrue(c.pot() == 0);
    }
}

