pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an address caller and a uint256 timestamp offset
    // We'll fuzz the caller and a timestamp we will set via vm.warp to influence the PRNG.
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and distinct from contract/bank to be a valid EOA
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // TICKET_AMOUNT is 10 in the contract; ensure we use that exact amount
        uint256 ticket = 10;

        // Bound the timestamp to a reasonable range to keep fuzz wide but concrete
        ts = bound(ts, 1, type(uint32).max);

        // We need to force the internal PRNG value to be 0. The PRNG is
        // keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender)) % 2
        // We can control block.timestamp (vm.warp) and msg.sender (vm.prank) but not block.difficulty.
        // However, for any given caller and timestamp there exists some difficulty parity (even/odd)
        // that makes the keccak hash LSB equal to 0. We cannot set difficulty via allowed cheatcodes,
        // but we can instead search for a timestamp (within fuzz) that yields the desired parity by
        // trying two consecutive timestamps (ts and ts+1) — this keeps domain wide and admissible.

        // We'll try ts and ts+1: pick the one that makes the PRNG result 0 for the given caller.
        // To compute the PRNG here off-chain we mimic the contract hashing using the current block.difficulty.
        // We only can control timestamp and caller; since difficulty is fixed in the test environment by default,
        // trying two timestamps suffices in practice to find one with PRNG==0 for the reference run.

        bool found = false;
        uint256 chosenTs = ts;
        for (uint i = 0; i < 2; i++) {
            uint256 t = ts + i;
            // compute the same hash operation as contract uses (using current vm.blockDifficulty())
            uint256 difficulty = block.difficulty;
            uint256 random = uint256(keccak256(abi.encodePacked(t, difficulty, caller))) % 2;
            if (random == 0) {
                chosenTs = t;
                found = true;
                break;
            }
        }

        // If neither ts nor ts+1 yield random==0 with the current block.difficulty, skip this input
        vm.assume(found);

        // Prepare caller with funds and set timestamp
        vm.deal(caller, ticket);
        vm.warp(chosenTs);

        // Record pot before
        uint256 before = c.pot();

        // Call play as the fuzzed caller with exact ticket amount
        vm.prank(caller);
        c.play{value: ticket}();

        // After the call, when the PRNG computed in the contract is 0 the reference resets pot to 0.
        // Our admissible domain ensured that the chosenTs and caller produce random==0 for the CURRENT
        // block.difficulty, so the reference MUST have pot == 0. The mutant (which checks random==1)
        // will in that case leave pot == before + ticket, so the assertion will fail on the mutant for
        // those inputs.
        assertTrue(c.pot() == 0);
    }
}

