pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a seed tweak (as uint256) that will influence msg.sender in the PRNG
    function testFuzz_property(address caller, uint256 seedTweak) public {
        // Keep admissible domain: caller must be nonzero and not the bank (deployer)
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Arrange: ensure pot is nonzero before the decisive call by making one play from some other account
        address starter = address(0xABBA);
        vm.deal(starter, 1 ether);
        vm.prank(starter);
        // first play: use correct ticket amount
        c.play{value: 10}();

        // Now pot may be 0 or 10 depending on randomness; we want the scenario where pot is nonzero before our decisive call
        // Require pot != 0 to be in the admissible domain for this property
        vm.assume(c.pot() != 0);

        // We need to control block.timestamp/block.difficulty somewhat to bias the PRNG outcome for the decisive call.
        // Use seedTweak to shift block.timestamp so fuzzer can find a timestamp producing random==0.
        uint256 newTs = block.timestamp + (seedTweak % 1000);
        vm.warp(newTs);

        // Give the caller some balance
        vm.deal(caller, 1 ether);
        // Execute the decisive call from fuzzed caller
        vm.prank(caller);
        c.play{value: 10}();

        // The general rule to assert: if the internal random computed for this call was 0, the reference contract will have reset pot to 0.
        // We cannot directly read the PRNG, but we can re-compute it deterministically here using the same inputs the contract used.
        uint256 recomputed = uint256(keccak256(abi.encodePacked(uint256(newTs), block.difficulty, caller))) % 2;

        // Only assert the universal property in the admissible subdomain where recomputed == 0
        if (recomputed == 0) {
            // Reference C should have pot == 0 for all such admissible inputs; the mutant (flipped condition) will fail for some.
            assertTrue(c.pot() == 0);
        }
    }
}

