pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller address and a timestamp value that will influence the PRNG
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller nonzero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Constrain timestamp to a reasonable range but wide enough
        ts = bound(ts, 1, type(uint64).max);

        // Arrange: give caller some ETH to play twice
        uint256 ticket = 10; // must match contract's TICKET_AMOUNT
        vm.deal(caller, ticket * 2);

        // We will freeze block.timestamp to ts and block.difficulty to a constant so PRNG is deterministic
        vm.warp(ts);
        vm.roll(1);
        // record initial pot
        uint256 potBefore = c.pot();

        // First play
        vm.prank(caller);
        c.play{value: ticket}();
        uint256 potAfterFirst = c.pot();

        // Keep same block state so PRNG outcome for same caller will be same
        vm.warp(ts);
        vm.roll(1);

        // Second play
        vm.prank(caller);
        c.play{value: ticket}();
        uint256 potAfterSecond = c.pot();

        // The universal rule we assert: if the PRNG outcome for this caller and ts equals 0,
        // then after any play the reference resets pot to 0; equivalently, under the reference
        // performing two identical plays with identical block state results in pot either being
        // 0 after a winning play or accumulating otherwise; we assert that after two identical plays
        // with identical PRNG input, the pot is either 0 (if PRNG triggered a reset) or equals potBefore + 2*ticket
        // (if PRNG did not trigger a reset). This is a property the reference satisfies for all admissible inputs
        // but the mutant (which flips the PRNG condition) will differ for some inputs.

        // Compute the observed final pot and check it matches one of the two allowed outcomes under reference
        bool ok = (potAfterSecond == 0) || (potAfterSecond == potBefore + 2 * ticket);
        assertTrue(ok);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test function: perform two plays where the second is a winning play
    // We cannot force randomness, so we model by making a play that could win and then assert that if a win occurred, pot becomes zero.
    // To observe a win we check that caller received funds by comparing balances before/after.

    function test_win_empties_pot(uint deposit1, uint deposit2) public payable {
        // require inputs equal contract constants sizes
        require(deposit1 == c.TICKET_AMOUNT());
        require(deposit2 == c.TICKET_AMOUNT());
        // ensure this contract has enough balance to pay both ticket amounts
        require(address(this).balance >= deposit1 + deposit2);

        // first play: add to pot
        c.play{value: deposit1}();

        // record balances before second play
        uint beforePlayer = address(this).balance;
        uint beforeContract = address(c).balance;

        // second play which may win; if it wins the contract will transfer pot-FEE_AMOUNT to this caller
        c.play{value: deposit2}();

        uint afterPlayer = address(this).balance;
        uint afterContract = address(c).balance;

        // determine if the second play was a win by observing that this caller's balance increased by pot - FEE_AMOUNT
        // The amount gained by player equals (beforeContract + deposit2) - c.FEE_AMOUNT() if win, otherwise 0
        // So compute expectedGainIfWin = beforeContract + deposit2 - FEE_AMOUNT
        uint expectedGainIfWin = beforeContract + deposit2 - c.FEE_AMOUNT();
        uint actualGain = afterPlayer < beforePlayer ? 0 : afterPlayer - beforePlayer;

        // If the second play was a win (actualGain == expectedGainIfWin), then the contract's pot must be zero afterwards.
        // This asserts: if win observed then c.pot() == 0
        assert(!(actualGain == expectedGainIfWin) || c.pot() == 0);
    }

    // allow funding this contract in tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // send exactly one ticket amount
        uint amount = 10;
        require(msg.value == amount, "must send exactly one ticket amount");
        // call play with the required payment
        c.play{value: amount}();
        // After a winning play the pot should be emptied (i.e., less than one ticket)
        // Observe via public getter pot()
        uint potAfter = c.pot();
        assert(potAfter < amount);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        // must provide exactly the ticket amount when calling play
        require(amount == 10);
        require(address(this).balance >= amount);

        uint pot_before = c.pot();

        // call play sending the ticket amount
        c.play{value: amount}();

        uint pot_after = c.pot();

        // If the play resulted in a payout that lowered the pot, then the decrease must be at least the ticket amount
        // This captures that the original resets pot (reducing by previous pot value), whereas the mutant can leave pot increased by amount.
        assert(pot_before - pot_after >= amount || pot_after >= pot_before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(address(this).balance >= 10);
        // send exactly one ticket amount so play proceeds
        c.play{value: 10}();
        // Observe whether the contract paid out to the player by comparing
        // the contract's Ether balance change: if the contract's balance decreased
        // by more than the fixed fee, then a payout to the player happened.
        // We cannot directly observe historical balances here, so instead we use
        // the invariant that after such a payout the stored pot must equal
        // address(c).balance + fee (since pot was cleared to 0 and the only
        // leftover in contract is the fee). FEE_AMOUNT is 1 per C definition.
        uint fee = 1;
        assert(c.pot() == address(c).balance + fee);
    }
    receive() external payable { }
}

