import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor and a seed used to influence block timestamp/difficulty via vm.warp/vm.roll
    function testFuzz_property(address player, uint48 seed) public {
        // admissible domain: player must be non-zero and not the contract deployer (bank)
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        // Give player enough Ether to buy a ticket
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // Use seed to vary block timestamp and block number to influence the PRNG
        // Keep wide bounds so fuzzer can find a winning case
        vm.warp(uint256(seed));
        vm.roll(uint256(seed));

        // perform the play call as the fuzzed player
        vm.prank(player);
        c.play{value: ticket}();

        // The universal property (single assertion): if the play resulted in a payout to the player (i.e. pot was reset to 0 in the reference), then pot must equal 0.
        // We can only observe pot via the public getter. The reference contract always sets pot to 0 after a winning play, but the mutant sometimes leaves pot > 0.
        // So assert that pot is either zero (winning payout happened and pot reset) OR pot equals ticket (no win and pot increased by ticket).
        // This covers all admissible behaviors of the correct contract for any single play: pot is either 0 (win) or ticket (lose) after one play from zero initial pot.
        uint p = c.pot();
        assertTrue(p == 0 || p == ticket);
    }
}

