pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We'll fuzz the caller address so the PRNG that depends on msg.sender may hit the winning branch.
    // The rule we assert: after a caller pays exactly TICKET_AMOUNT in a play(), if the contract's balance decreased
    // by (pot_old - FEE_AMOUNT) (meaning a payout happened), then the reference contract always sets pot to 0.
    // The mutant leaves pot == FEE_AMOUNT in that payout case. We express this by recording pre-call pot and
    // contract balance, executing play(), and then when the contract balance decreased by the expected payout
    // amount, we assert that c.pot() == 0.

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // Keep fuzz domain wide but avoid the zero address to ensure vm.prank works sensibly.
        vm.assume(caller != address(0));

        uint TICKET = 10;
        uint FEE = 1;

        // Give the caller enough ETH to pay the ticket
        vm.deal(caller, TICKET);

        // Seed the pot with some previous plays so pot_old may be > 0. Make two prior contributions from other addresses
        // (use two different fuzz-insensitive addresses) to avoid tightly constraining the domain.
        address seed1 = address(0x1001);
        address seed2 = address(0x1002);
        vm.deal(seed1, TICKET);
        vm.deal(seed2, TICKET);
        vm.prank(seed1);
        c.play{value: TICKET}();
        vm.prank(seed2);
        c.play{value: TICKET}();

        // Record pre-call state
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;

        // Caller plays once, paying exactly the ticket amount
        vm.prank(caller);
        c.play{value: TICKET}();

        uint pot_after = c.pot();
        uint bal_after = address(c).balance;

        // If a payout occurred, the contract balance should have decreased by (pot_before + TICKET - FEE) - pot_after
        // In the reference, on a win pot_after == 0 and balance decreases by (pot_before + TICKET - FEE)
        // In the mutant, on a win pot_after == FEE and balance decreases by (pot_before + TICKET - FEE) - FEE
        // We avoid making assumptions about randomness outcome; instead we detect whether a full payout happened by
        // checking that the balance decreased by exactly (pot_before + TICKET - FEE).

        uint expected_full_payout = pot_before + TICKET - FEE;
        bool fullPayoutHappened = (bal_before >= bal_after) && (bal_before - bal_after == expected_full_payout);

        // The single universal assertion: whenever the contract's balance decreased by expected_full_payout (i.e., a
        // full payout occurred to the caller), the correct contract always sets pot to 0. The mutant can leave pot==FEE,
        // causing this assertion to fail for some caller that wins.
        assertTrue(!fullPayoutHappened || pot_after == 0);
    }
}

